// Copies the OpenAPI client generated by the Vue app (@hey-api/openapi-ts) into
// src/lib/api/generated, dropping the ".js" extension from relative imports:
// the generator emits ESM-style "./client/index.js" specifiers that TypeScript
// maps to .ts files but Turbopack does not resolve.
//
// Usage: pnpm sync:api   (re-run whenever the Vue app regenerates its client)
import fs from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

const here = path.dirname(fileURLToPath(import.meta.url))
const source = path.resolve(here, "../../frontend-src/frontend/src/client/generated")
const target = path.resolve(here, "../src/lib/api/generated")

if (!fs.existsSync(source)) {
  console.error(`Generated client not found at ${source}`)
  process.exit(1)
}

fs.rmSync(target, { recursive: true, force: true })

let files = 0
function copyDir(from, to) {
  fs.mkdirSync(to, { recursive: true })
  for (const entry of fs.readdirSync(from, { withFileTypes: true })) {
    const src = path.join(from, entry.name)
    const dest = path.join(to, entry.name)
    if (entry.isDirectory()) {
      copyDir(src, dest)
      continue
    }
    const code = fs
      .readFileSync(src, "utf8")
      .replace(/(from\s+['"])(\.{1,2}\/[^'"]+?)\.js(['"])/g, "$1$2$3")
    fs.writeFileSync(dest, code)
    files++
  }
}

copyDir(source, target)
console.log(`Synced ${files} files into ${path.relative(process.cwd(), target)}`)
